# Twin of t133: smallest positive N with 11 + 30N not prime: 41, 71, 101, 131 are prime, 161 = 7 * 23.
def isprime(m):
    return m > 1 and all(m % d for d in range(2, int(m ** 0.5) + 1))
assert isprime(11)          # N = 0 gives a prime, so D' (which lacks 0 < n) is still only a lower bound
N = 1
while isprime(11 + 30 * N):
    N += 1
print([11 + 30 * k for k in range(1, N + 1)])
